p='packages/babel-traverse/src/scope/lib/renamer.ts'
s=open(p).read()
s=s.replace('''  "AssignmentExpression|Declaration|VariableDeclarator"(''','''  ObjectProperty: {
    exit({ node }, state) {
      if (!node.shorthand) return;
      let { value } = node;
      if (t.isAssignmentPattern(value)) value = value.left;
      if (!t.isIdentifier(value) || !t.isIdentifier(node.key)) return;
      if (
        value.name !== node.key.name ||
        (value === state.binding.identifier && state.oldName !== state.newName)
      ) {
        node.shorthand = false;
        if (node.extra?.shorthand) node.extra.shorthand = false;
      }
    },
  },

  "AssignmentExpression|Declaration|VariableDeclarator"(''',1)
open(p,'w').write(s)
